import React from 'react';
import {AbsoluteFill, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';

const KNOT_FRAMES = [0, 3, 4, 6, 10, 15, 20, 30, 40, 50, 60, 70, 80, 90, 100, 110, 115, 120, 124, 128, 129, 132, 135, 138];
const D_CENTERS = [-550, -447, -353, -269, -195, -131, -87, -41, -11, 15, 36, 54, 72, 91, 112, 143, 166, 198, 242, 322, 350, 480, 630, 780];
const DEFAULT_OFFSETS = [0, 69, 113, 150, 201, 245, 291, 351, 412, 479];

function pathAt(x) {
  const phase = 2 * Math.PI * x / 595;
  const y = 155.29 + 38.84 * Math.sin(phase) + 6.42 * Math.cos(phase);
  const slope = (2 * Math.PI / 595) * (38.84 * Math.cos(phase) - 6.42 * Math.sin(phase));
  return {y, angle: Math.atan(slope) * 180 / Math.PI};
}

export default function OpeningTitle({data}) {
  const frame = useCurrentFrame();
  const {durationInFrames, width, height} = useVideoConfig();
  const text = String(data.text || 'DAILY VLOG');
  const chars = text.split('');
  const anchor = interpolate(frame, KNOT_FRAMES, D_CENTERS, {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  });
  const offsets = text === 'DAILY VLOG'
    ? DEFAULT_OFFSETS
    : chars.map((_, i) => i * 54);

  return <AbsoluteFill style={{overflow: 'hidden'}}>
    {chars.map((ch, i) => {
      if (ch === ' ') return null;
      const x = anchor + offsets[i];
      const {y, angle} = pathAt(x);
      return <div key={i} style={{position: 'absolute', left: x * width / 576,
        top: y * height / 324, transform: `translate(-50%, -50%) rotate(${angle}deg) scaleX(0.84)`,
        fontFamily: data.fontFamily || 'Gill Sans, Arial Black, sans-serif',
        fontSize: data.fontSize || 255, fontWeight: 900, lineHeight: 1,
        color: data.color || '#FEDC5E'}}>{ch}</div>;
    })}
  </AbsoluteFill>;
}

programs.MIDDLE:
import React from 'react';
import {AbsoluteFill, useCurrentFrame} from 'remotion';

// The source video is 30 fps. This graphic begins on draft frame 136.
// Each value is the first local frame on which that character is visible.
const REVEAL_FRAMES = [7, 9, 10, 18, 19, 21, 22, 29, 30, 31, 32, 34, 35, 35, 36, 38, 40, 48, 49, 51, 51];

export default function Middle({data}) {
  const frame = useCurrentFrame();
  const phrase = String(data.text || 'JUST EVERYDAY MOMENTS');
  const schedule = phrase === 'JUST EVERYDAY MOMENTS'
    ? REVEAL_FRAMES
    : Array.from({length: phrase.length}, (_, i) => 7 + i * 2);
  const count = schedule.filter(at => frame >= at).length;
  const visible = phrase.slice(0, count);
  const fontSize = data.fontSize || 73;
  return <AbsoluteFill style={{overflow: 'hidden'}}>
    <div style={{
      position: 'absolute', left: '50%', top: '50%',
      transform: 'translate(-50%, -50%)', width: 'max-content',
      fontFamily: data.fontFamily || 'Georgia, serif', fontSize,
      fontWeight: 700, color: data.color || '#FFFFFF',
      textShadow: '0 2px 6px rgba(0,0,0,.25)', whiteSpace: 'nowrap',
    }}>
      <span style={{visibility: 'hidden'}}>{phrase}</span>
      <div style={{position: 'absolute', left: 0, top: 0, display: 'flex', alignItems: 'center'}}>
        <span>{visible}</span>
        {frame < 59 && <span style={{display: 'inline-block', width: 4, height: fontSize * .88, backgroundColor: '#fff', marginLeft: 2}} />}
      </div>
    </div>
  </AbsoluteFill>;
}

