import React from 'react';
import {AbsoluteFill, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';

// Source-video frame numbers minus the graphic's placement at draft frame 527.
const REVEAL_FRAMES = [3, 5, 6, 13, 14, 15, 21, 22, 23, 24, 25, 26, 26, 27, 28, 30, 31, 38, 39];

export default function Ending({data}) {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const phrase = String(data.text || 'THANKS FOR WATCHING');
  const schedule = phrase === 'THANKS FOR WATCHING'
    ? REVEAL_FRAMES
    : Array.from({length: phrase.length}, (_, i) => 3 + i * 2);
  const count = schedule.filter(at => frame >= at).length;
  const visible = phrase.slice(0, count);
  const fontSize = data.fontSize || 43;
  const black = interpolate(frame, [0, 34, durationInFrames], [0, 0, .9], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  });
  return <AbsoluteFill style={{backgroundColor: `rgba(0,0,0,${black})`}}>
    <div style={{
      position: 'absolute', left: '50%', top: '50%',
      transform: 'translate(-50%, -50%)', width: 'max-content',
      fontFamily: data.fontFamily || 'Avenir Next Demi Bold, Avenir Next, sans-serif', fontSize,
      fontWeight: 700, lineHeight: 1, letterSpacing: data.letterSpacing ?? 1.2,
      color: data.color || '#FFFFFF', whiteSpace: 'nowrap',
    }}>
      <span style={{visibility: 'hidden'}}>{phrase}</span>
      <div style={{position: 'absolute', left: 0, top: 0, display: 'flex', alignItems: 'center'}}>
        <span>{visible}</span>
        {frame < 43 && <span style={{display: 'inline-block', width: 3, height: fontSize * .9, backgroundColor: '#fff', marginLeft: 1}} />}
      </div>
    </div>
  </AbsoluteFill>;
}
